var calc_output = [];

var af = parseFloat(af);
var sp = parseFloat(sp);
var eratio = parseFloat(eratio);
var bmi = parseFloat(bmi);
var age = parseFloat(age);

var y = -9.19174463966566 + 0.0451129471272832*age + 0.130730156015681*bmi + 0.0858634402456586*eratio + 0.051963758732548*sp + 1.69968057294513*af;

var z = Math.pow(Math.E,y);

var prob = (z/(1 + z))*100; 

prob = prob.toFixed(1);

//results
calc_output.push({
    name: 'mini',
    value: prob,
    value_text: '%',
    message: 'Probability of heart failure with preserved EF'
});
